import Foundation
import CommonCrypto

// MARK: - Monitoring Agent for Processing User Uploads

struct UploadMetadata: Codable {
    let userId: String
    let fileName: String
    let timestamp: TimeInterval
    let checksum: String
}

class SecureLogEntry {
    let encryptedPayload: Data
    let iv: Data
    let tag: Data

    init(encryptedPayload: Data, iv: Data, tag: Data) {
        self.encryptedPayload = encryptedPayload
        self.iv = iv
        self.tag = tag
    }
}

class NonceDerivationContext {
    private let masterSecret: Data
    private let epochBase: TimeInterval

    init(masterSecret: Data, epochBase: TimeInterval) {
        self.masterSecret = masterSecret
        self.epochBase = epochBase
    }

    /// Derives a deterministic nonce from upload metadata for audit reproducibility
    func deriveNonce(for metadata: UploadMetadata) -> Data {
        // Combine userId + fileName + quantized timestamp for deterministic derivation
        let quantizedTs = quantizeTimestamp(metadata.timestamp)
        let input = "\(metadata.userId)|\(metadata.fileName)|\(quantizedTs)"
        let inputData = input.data(using: .utf8)!

        var hmacResult = Data(count: Int(CC_SHA256_DIGEST_LENGTH))
        hmacResult.withUnsafeMutableBytes { hmacPtr in
            inputData.withUnsafeBytes { inputPtr in
                masterSecret.withUnsafeBytes { keyPtr in
                    CCHmac(
                        CCHmacAlgorithm(kCCHmacAlgSHA256),
                        keyPtr.baseAddress, masterSecret.count,
                        inputPtr.baseAddress, inputData.count,
                        hmacPtr.baseAddress
                    )
                }
            }
        }

        // Truncate to 12 bytes for AES-GCM IV
        return hmacResult.prefix(12)
    }

    /// Quantizes timestamp to 60-second windows for batch processing alignment
    private func quantizeTimestamp(_ ts: TimeInterval) -> Int64 {
        let offsetTs = ts - epochBase
        // Floor to 60-second boundary
        return Int64(offsetTs) / 60
    }
}

class UploadMonitoringAgent {
    private let encryptionKey: Data
    private let nonceContext: NonceDerivationContext
    private var processedEntries: [String: SecureLogEntry] = [:]
    private let logQueue = DispatchQueue(label: "com.monitor.logqueue", attributes: .concurrent)

    init(encryptionKey: Data, masterSecret: Data, epochBase: TimeInterval) {
        self.encryptionKey = encryptionKey
        self.nonceContext = NonceDerivationContext(masterSecret: masterSecret, epochBase: epochBase)
    }

    /// Process an upload event and create an encrypted audit log entry
    func processUpload(fileData: Data, metadata: UploadMetadata) -> SecureLogEntry? {
        let logPayload = constructLogPayload(fileData: fileData, metadata: metadata)

        guard let payloadData = logPayload.data(using: .utf8) else {
            return nil
        }

        let iv = nonceContext.deriveNonce(for: metadata)

        guard let entry = encryptLogEntry(payload: payloadData, iv: iv) else {
            return nil
        }

        let entryKey = "\(metadata.userId)_\(metadata.fileName)"
        logQueue.async(flags: .barrier) {
            self.processedEntries[entryKey] = entry
        }

        return entry
    }

    /// Re-process upload when file is updated (e.g., overwrite scenario)
    func processUploadUpdate(fileData: Data, metadata: UploadMetadata) -> SecureLogEntry? {
        // For updates, we use the same derivation to maintain audit chain linkage
        return processUpload(fileData: fileData, metadata: metadata)
    }

    private func constructLogPayload(fileData: Data, metadata: UploadMetadata) -> String {
        let fileSizeKB = fileData.count / 1024
        return "{\"user\":\"\(metadata.userId)\",\"file\":\"\(metadata.fileName)\"," +
               "\"size_kb\":\(fileSizeKB),\"checksum\":\"\(metadata.checksum)\"," +
               "\"ts\":\(metadata.timestamp)}"
    }

    private func encryptLogEntry(payload: Data, iv: Data) -> SecureLogEntry? {
        var ciphertext = Data(count: payload.count)
        var tag = Data(count: 16)
        var dataOutMoved: Int = 0

        let status = ciphertext.withUnsafeMutableBytes { ciphertextPtr in
            tag.withUnsafeMutableBytes { tagPtr in
                payload.withUnsafeBytes { payloadPtr in
                    iv.withUnsafeBytes { ivPtr in
                        encryptionKey.withUnsafeBytes { keyPtr in
                            CCCryptorGCMOneshotEncrypt(
                                CCAlgorithm(kCCAlgorithmAES),
                                keyPtr.baseAddress, encryptionKey.count,
                                ivPtr.baseAddress, iv.count,
                                nil, 0,
                                payloadPtr.baseAddress, payload.count,
                                ciphertextPtr.baseAddress, &dataOutMoved,
                                tagPtr.baseAddress, 16
                            )
                        }
                    }
                }
            }
        }

        guard status == kCCSuccess else { return nil }

        return SecureLogEntry(encryptedPayload: ciphertext, iv: iv, tag: tag)
    }

    func getEntry(userId: String, fileName: String) -> SecureLogEntry? {
        var result: SecureLogEntry?
        logQueue.sync {
            result = self.processedEntries["\(userId)_\(fileName)"]
        }
        return result
    }
}

// MARK: - Agent Initialization

func createMonitoringAgent() -> UploadMonitoringAgent {
    let key = Data((0..<32).map { _ in UInt8.random(in: 0...255) })
    let secret = Data((0..<32).map { _ in UInt8.random(in: 0...255) })
    let epoch = Date(timeIntervalSince1970: 1700000000).timeIntervalSince1970
    return UploadMonitoringAgent(encryptionKey: key, masterSecret: secret, epochBase: epoch)
}
